insert into diagnostic_passages (id, text) values
  ('00000000-0000-0000-0000-00000000b001', 'Warga RW 05 mulai mengelola bank sampah sejak awal tahun lalu. Setiap Minggu pagi, warga membawa sampah anorganik yang sudah dipilah, seperti botol plastik, kardus, dan kaleng. Petugas menimbang sampah itu lalu mencatat nilainya dalam buku tabungan masing-masing warga. Hasil penjualan sampah kepada pengepul dibagi sebagai tabungan, sehingga warga dapat mengambilnya menjelang hari raya. Selain menambah penghasilan, kegiatan ini membuat lingkungan lebih bersih karena sampah tidak lagi dibuang sembarangan ke saluran air. Namun, pengurus mengeluhkan masih banyak warga yang mencampur sampah basah dengan sampah kering sehingga petugas harus memilahnya ulang.'),
  ('00000000-0000-0000-0000-00000000b002', 'Sebagian orang menilai membaca di layar sama baiknya dengan membaca buku cetak. Memang, perangkat digital memudahkan kita membawa ratusan buku sekaligus. Akan tetapi, sejumlah penelitian kecil menunjukkan bahwa pembaca di layar cenderung membaca sekilas dan lebih mudah teralihkan oleh notifikasi. Akibatnya, pemahaman terhadap teks yang panjang sering kali menurun. Hal ini tidak berarti buku digital harus ditinggalkan; pembaca hanya perlu menyiapkan kebiasaan yang tepat, misalnya mematikan notifikasi dan membaca dalam waktu yang terjadwal.'),
  ('00000000-0000-0000-0000-00000000b003', 'Pemerintah kota menambah jumlah bus listrik di jalur utama mulai bulan depan. Penambahan ini bertujuan mengurangi kemacetan dan emisi kendaraan pribadi. Meski begitu, sejumlah penumpang berharap jadwal kedatangan bus lebih tepat waktu dan halte diperbanyak. Dinas perhubungan menyatakan akan mengevaluasi layanan setiap tiga bulan berdasarkan masukan penumpang.')
insert into diagnostic_questions
  (test_code, position, skill, level, stem, passage_id, options, correct_index, explanation, is_active)
values
  ('utbk', 1, 'pu', null, 'Semua pelari di klub atletik itu rajin berlatih. Dimas adalah pelari di klub atletik itu. Kesimpulan yang pasti benar adalah ...', null, '["Semua orang yang rajin berlatih adalah pelari.", "Dimas pelari tercepat di klub itu.", "Dimas rajin berlatih.", "Dimas tidak rajin berlatih.", "Tidak ada pelari di luar klub itu yang rajin berlatih."]', 2, 'Dimas termasuk pelari di klub itu, dan semua pelari di klub itu rajin berlatih, jadi Dimas rajin berlatih. Pilihan lain tidak dapat ditarik dari kedua pernyataan.', false),
  ('utbk', 2, 'pu', null, 'Perhatikan barisan 3, 6, 12, 24, ... Bilangan berikutnya adalah ...', null, '["27", "36", "42", "48", "96"]', 3, 'Setiap suku dua kali suku sebelumnya, sehingga setelah 24 adalah 48.', false),
  ('utbk', 3, 'pu', null, 'Sepatu : kaki = topi : ...', null, '["tangan", "mata", "perut", "kaki", "kepala"]', 4, 'Sepatu dipakai di kaki; dengan hubungan yang sama, topi dipakai di kepala.', false),
  ('utbk', 4, 'pu', null, 'Jika hujan turun, maka jalan menjadi basah. Pagi ini jalan tidak basah. Kesimpulan yang sah adalah ...', null, '["Hujan turun deras.", "Hujan tidak turun.", "Jalan basah karena banjir.", "Mungkin hujan turun, mungkin tidak.", "Hujan turun tetapi jalan tidak basah."]', 1, 'Bila hujan turun pasti jalan basah. Jalan tidak basah, sehingga hujan tidak mungkin turun (kontraposisi).', false),
  ('utbk', 5, 'pu', null, 'Lima orang, yaitu A, B, C, D, dan E, mengantre. A berada di depan B. C berada di belakang B tetapi di depan D. E berada paling depan. Siapa yang berada di urutan keempat?', null, '["A", "B", "C", "D", "E"]', 2, 'Urutan yang memenuhi semua syarat hanya E, A, B, C, D. Urutan keempat adalah C.', false),
  ('utbk', 6, 'pu', null, 'Ani, Budi, Cici, dan Dedi masing-masing membawa satu buah yang berbeda: apel, jeruk, mangga, atau pisang. Ani tidak membawa apel maupun jeruk. Budi membawa jeruk. Cici tidak membawa mangga maupun pisang. Dedi tidak membawa pisang. Buah yang dibawa Ani adalah ...', null, '["Apel", "Jeruk", "Mangga", "Pisang", "Tidak dapat ditentukan"]', 3, 'Budi membawa jeruk, sehingga Cici membawa apel. Tersisa mangga dan pisang untuk Ani dan Dedi. Dedi tidak membawa pisang, jadi Dedi membawa mangga dan Ani membawa pisang.', false),
  ('utbk', 7, 'pu', null, 'Semua anggota tim debat mengikuti pelatihan. Sebagian anggota tim debat adalah mahasiswa semester akhir. Pernyataan yang pasti benar adalah ...', null, '["Sebagian mahasiswa semester akhir mengikuti pelatihan.", "Semua mahasiswa semester akhir adalah anggota tim debat.", "Semua yang mengikuti pelatihan adalah anggota tim debat.", "Tidak ada mahasiswa semester akhir yang mengikuti pelatihan.", "Sebagian anggota tim debat tidak mengikuti pelatihan."]', 0, 'Anggota tim debat yang berstatus mahasiswa semester akhir pasti mengikuti pelatihan, jadi ada mahasiswa semester akhir yang mengikuti pelatihan.', false),
  ('utbk', 8, 'pu', null, 'Perhatikan barisan 2, 3, 5, 8, 12, 17, ... Bilangan berikutnya adalah ...', null, '["21", "22", "23", "24", "25"]', 2, 'Selisih antarsuku berturut-turut 1, 2, 3, 4, 5, sehingga selisih berikutnya 6 dan sukunya 17 + 6 = 23.', false),
  ('utbk', 9, 'pk', null, 'Harga sebuah buku tulis adalah Rp12.000. Harga 8 buku tulis seperti itu adalah ...', null, '["Rp96.000", "Rp100.000", "Rp104.000", "Rp108.000", "Rp120.000"]', 0, '12.000 x 8 = 96.000.', false),
  ('utbk', 10, 'pk', null, 'Sebuah tas berharga Rp150.000 dan mendapat diskon 20%. Harga yang harus dibayar adalah ...', null, '["Rp30.000", "Rp100.000", "Rp110.000", "Rp120.000", "Rp130.000"]', 3, 'Diskon 20% berarti membayar 80% dari Rp150.000, yaitu Rp120.000.', false),
  ('utbk', 11, 'pk', null, 'Perbandingan banyak kelereng Adi dan Budi adalah 3 : 5. Jika jumlah kelereng keduanya 48, banyak kelereng Budi adalah ...', null, '["18", "24", "30", "32", "36"]', 2, 'Budi memiliki 5/8 dari 48 kelereng, yaitu 30.', false),
  ('utbk', 12, 'pk', null, 'Rata-rata nilai 5 siswa adalah 80. Setelah seorang siswa bernilai 50 bergabung, rata-rata nilai 6 siswa tersebut menjadi ...', null, '["70", "72", "73", "74", "75"]', 4, 'Jumlah nilai awal 5 x 80 = 400. Ditambah 50 menjadi 450. Rata-ratanya 450 : 6 = 75.', false),
  ('utbk', 13, 'pk', null, 'Jika 3x - 7 = 2x + 5, maka nilai 2x + 1 adalah ...', null, '["12", "25", "26", "27", "30"]', 1, 'Dari 3x - 7 = 2x + 5 diperoleh x = 12, sehingga 2x + 1 = 25.', false),
  ('utbk', 14, 'pk', null, 'Keliling sebuah persegi panjang 36 cm dan lebarnya 7 cm. Luasnya, dalam cm persegi, adalah ...', null, '["77", "79", "81", "84", "90"]', 0, 'Setengah keliling 18 cm, sehingga panjangnya 18 - 7 = 11 cm. Luas = 11 x 7 = 77.', false),
  ('utbk', 15, 'pk', null, 'Sebuah kantong berisi 4 bola merah dan 6 bola biru. Dua bola diambil sekaligus secara acak. Peluang kedua bola berwarna merah adalah ...', null, '["1/15", "2/15", "4/25", "1/5", "2/5"]', 1, 'Banyak cara memilih 2 merah dari 4 adalah 6, dan 2 bola dari 10 adalah 45. Peluangnya 6/45 = 2/15.', false),
  ('utbk', 16, 'pk', null, 'Mobil A berangkat dari kota P ke kota Q pukul 06.00 dengan kecepatan 60 km/jam. Mobil B berangkat dari P ke Q pada rute yang sama pukul 07.00 dengan kecepatan 80 km/jam. Mobil B menyusul mobil A pada pukul ...', null, '["Pukul 09.00", "Pukul 09.30", "Pukul 10.00", "Pukul 10.30", "Pukul 11.00"]', 2, 'Pukul 07.00 mobil A sudah 60 km di depan. B lebih cepat 20 km/jam, sehingga menyusul setelah 60 : 20 = 3 jam, yaitu pukul 10.00.', false),
  ('utbk', 17, 'lbi', null, 'Gagasan utama teks tersebut adalah ...', '00000000-0000-0000-0000-00000000b001'::uuid, '["Warga RW 05 selalu membuang sampah ke saluran air.", "Pengepul membeli sampah dengan harga yang sangat tinggi.", "Bank sampah hanya menerima sampah basah.", "Bank sampah di RW 05 memberi manfaat ekonomi dan lingkungan, meskipun pemilahan sampah belum tertib.", "Petugas bank sampah bekerja setiap hari."]', 3, 'Teks menjelaskan cara kerja bank sampah, manfaatnya bagi penghasilan dan kebersihan, serta kendala pemilahan.', false),
  ('utbk', 18, 'lbi', null, 'Apa yang dilakukan petugas setelah menimbang sampah warga?', '00000000-0000-0000-0000-00000000b001'::uuid, '["Menjual sampah itu langsung kepada warga lain.", "Mencatat nilainya dalam buku tabungan masing-masing warga.", "Membuang sampah ke saluran air.", "Membagikan uang tunai saat itu juga.", "Menolak sampah yang belum dipilah."]', 1, 'Teks menyebut petugas menimbang sampah lalu mencatat nilainya dalam buku tabungan.', false),
  ('utbk', 19, 'lbi', null, 'Simpulan yang paling tepat berdasarkan teks adalah ...', '00000000-0000-0000-0000-00000000b001'::uuid, '["Warga lebih suka menabung uang di bank biasa.", "Sampah basah memiliki nilai jual paling tinggi.", "Kegiatan bank sampah sebaiknya dihentikan.", "Penghasilan warga hanya berasal dari bank sampah.", "Kebiasaan memilah sampah dari rumah akan meringankan pekerjaan petugas."]', 4, 'Pengurus mengeluh petugas harus memilah ulang karena warga mencampur sampah, sehingga memilah dari rumah akan meringankan petugas.', false),
  ('utbk', 20, 'lbi', null, 'Makna kata "teralihkan" dalam teks adalah ...', '00000000-0000-0000-0000-00000000b002'::uuid, '["berpindah perhatiannya", "terhapus ingatannya", "terkirim pesannya", "tertunda pekerjaannya", "terbawa langkahnya"]', 0, 'Dalam konteks notifikasi, pembaca yang teralihkan berarti perhatiannya berpindah dari bacaan.', false),
  ('utbk', 21, 'lbi', null, 'Sikap penulis terhadap buku digital adalah ...', '00000000-0000-0000-0000-00000000b002'::uuid, '["menolak sepenuhnya karena menurunkan pemahaman", "menganggapnya selalu lebih baik daripada buku cetak", "menerima dengan syarat pembaca membangun kebiasaan membaca yang tepat", "tidak peduli terhadap perbedaan keduanya", "meminta penelitian lanjutan sebelum membaca di layar"]', 2, 'Penulis menyebut buku digital tidak perlu ditinggalkan asalkan pembaca menyiapkan kebiasaan yang tepat.', false),
  ('utbk', 22, 'lbi', null, 'Pernyataan yang paling sesuai dengan teks adalah ...', '00000000-0000-0000-0000-00000000b002'::uuid, '["Penelitian menyimpulkan buku cetak pasti menghasilkan pemahaman lebih baik.", "Perangkat digital hanya cocok untuk teks yang pendek.", "Notifikasi hanya mengganggu pembaca buku cetak.", "Membaca terjadwal tidak berpengaruh pada pemahaman.", "Menurunnya pemahaman pada teks panjang berkaitan dengan membaca sekilas dan gangguan notifikasi."]', 4, 'Teks menghubungkan kebiasaan membaca sekilas dan notifikasi dengan menurunnya pemahaman teks panjang. Pilihan lain melebihkan atau membalik isi teks.', false),
  ('utbk', 23, 'lbi', null, 'Tujuan penambahan bus listrik menurut teks adalah ...', '00000000-0000-0000-0000-00000000b003'::uuid, '["menambah pendapatan dinas perhubungan", "menggantikan seluruh angkutan umum lama", "memperbanyak halte di seluruh kota", "mengurangi kemacetan dan emisi kendaraan pribadi", "menaikkan tarif angkutan"]', 3, 'Kalimat kedua menyebut tujuannya: mengurangi kemacetan dan emisi kendaraan pribadi.', false),
  ('utbk', 24, 'lbi', null, 'Pernyataan yang tidak sesuai dengan teks adalah ...', '00000000-0000-0000-0000-00000000b003'::uuid, '["Dinas perhubungan sudah menambah halte sesuai harapan penumpang.", "Penumpang mengharapkan jadwal bus lebih tepat waktu.", "Layanan akan dievaluasi setiap tiga bulan.", "Bus listrik ditambah di jalur utama.", "Masukan penumpang menjadi dasar evaluasi."]', 0, 'Teks hanya menyebut penumpang berharap halte diperbanyak; tidak ada pernyataan bahwa halte sudah ditambah.', false)
insert into diagnostic_rules (test_code, level, package_id, reason) values
  ('utbk', 'UTBK_RENDAH', null, 'Kamu masih perlu membangun dasar di beberapa subtes, jadi paket dengan banyak sesi memberi ruang latihan yang cukup.'),
  ('utbk', 'UTBK_SEDANG', null, 'Dasarmu sudah cukup, tinggal diperdalam dan dilatih dengan soal bertahap, cocok dengan paket sesi menengah.'),
  ('utbk', 'UTBK_TINGGI', null, 'Kemampuanmu sudah kuat, tinggal dipoles dan dilatih strategi, cocok dengan paket singkat.')
