-- Seed: 24 soal UTBK mini orisinal (pu, pk, lbi) + aturan pita -> paket SNBT.
-- DIHASILKAN oleh build_utbk_seed.py dari utbk_questions.json; jangan diedit tangan.
-- Soal masuk NONAKTIF. Aktifkan hanya setelah soal lbi dibaca manusia yang pernah ikut UTBK:
--   update diagnostic_questions set is_active = true where test_code = 'utbk';
-- Aman dijalankan ulang (on conflict do nothing).

on conflict (id) do nothing;

on conflict (test_code, position) do nothing;

-- Aturan pita -> paket. package_id diisi lewat nama paket di katalog; null bila tidak ditemukan.
on conflict (test_code, level) do nothing;

update diagnostic_rules set package_id = (
  select id from packages where package_name ilike '%SNBT%SKS' order by package_name limit 1
) where test_code = 'utbk' and level = 'UTBK_RENDAH' and package_id is null;
update diagnostic_rules set package_id = (
  select id from packages where package_name ilike '%SNBT%Juara' order by package_name limit 1
) where test_code = 'utbk' and level = 'UTBK_SEDANG' and package_id is null;
update diagnostic_rules set package_id = (
  select id from packages where package_name ilike '%SNBT%Satset' order by package_name limit 1
) where test_code = 'utbk' and level = 'UTBK_TINGGI' and package_id is null;
